WITH `t0` AS (SELECT `tenantId`, `entityId`, `version`, `stock_index` FROM `metric_group_ots_component_indices` FINAL WHERE `tenantId` = {p0:String}) SELECT sum(`__typedhouse_input`.`version`) AS `versions`, sum(`__typedhouse_input`.`stock_index`) AS `stock` FROM (SELECT `m`.`version` AS `version`, `m`.`stock_index` AS `stock_index` FROM `t0` AS `m` INNER ALL JOIN (SELECT `tenantId`, `entityId`, max(`version`) AS `version` FROM `t0` GROUP BY `tenantId`, `entityId`) AS `v` ON `m`.`tenantId` = `v`.`tenantId` AND `m`.`entityId` = `v`.`entityId` AND `m`.`version` = `v`.`version`) AS `__typedhouse_input`
